//! OpenStitch's own stitch-pattern library and its file format (`openstitch.pattern`).
//!
//! Every bundled pattern is an original drawing generated by `tools/gen_patterns.py`; none is
//! derived from Brother's `.pmf`, `.pas` or `.plf` files. One JSON document per pattern:
//!
//! ```json
//! {"format": "openstitch.pattern", "version": 1, "kind": "motif", "id": "wave",
//!  "name": "Wave", "rowShift": 0.5, "paths": [[[0, 0], [0.5, -0.5], [1, 0]]]}
//! ```
//!
//! - `motif`: one path from (0, 0) to (1, 0); x runs along the sewing line (−0.5…1.5, so
//!   loops may overlap their neighbours), y across it in −1…1 (scaled by the motif height).
//!   Used by motif lines and motif fill.
//! - `fill`: paths in the unit tile [0, 1]²; programmable fill puts needle points on them.
//! - `decorative`: paths from (0, y₀) to (1, y₀) (x in −0.5…1.5, y in 0…1), so tiles chain into rows;
//!   rows repeat every tile height, shifted by `rowShift` tile widths. Used by decorative fill.
//!
//! A fill tile may also carry `regions`: embossed or engraved areas, each named by a point
//! (`at`, in the unit tile) inside a closed area its lines enclose (the tile repeats, so lines
//! that leave one side come back at the other). Programmable fill sews engraved areas with
//! short stitches and drops needle points inside embossed ones ([`RegionMask`]).

use crate::geometry::{Vec2, v2};
use serde::{Deserialize, Serialize};
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum PatternKind {
    Motif,
    Fill,
    Decorative,
}

/// A parsed, validated pattern. Serializes as an `openstitch.pattern` document; deserializing
/// validates it (so a damaged `.osd` cannot smuggle in a bad pattern).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(try_from = "PatternFile", into = "PatternFile")]
pub struct Pattern {
    pub kind: PatternKind,
    pub id: String,
    pub name: String,
    /// Decorative rows: horizontal shift of each row, in tile widths (0…1).
    pub row_shift: f64,
    pub paths: Vec<Vec<Vec2>>,
    /// Fill tiles: embossed and engraved areas, in the order they were applied.
    pub regions: Vec<PatternRegion>,
}

/// The effect of an area of a fill tile.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum RegionEffect {
    /// Sewn with short stitches (sunken look).
    Engrave,
    /// Sewn without needle points inside (raised look).
    Emboss,
}

/// An embossed or engraved area of a fill tile: the closed area around `at`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PatternRegion {
    pub effect: RegionEffect,
    pub at: Vec2,
}

#[derive(Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct RegionFile {
    effect: RegionEffect,
    at: [f64; 2],
}

/// Most `regions` in one pattern.
pub const MAX_REGIONS: usize = 256;

/// The JSON shape of an `openstitch.pattern` document.
#[derive(Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct PatternFile {
    format: String,
    version: u32,
    kind: PatternKind,
    id: String,
    name: String,
    #[serde(default, skip_serializing_if = "is_zero")]
    row_shift: f64,
    paths: Vec<Vec<[f64; 2]>>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    regions: Vec<RegionFile>,
}

fn is_zero(v: &f64) -> bool {
    *v == 0.0
}

impl TryFrom<PatternFile> for Pattern {
    type Error = String;
    fn try_from(f: PatternFile) -> Result<Self, String> {
        validate(f)
    }
}

impl From<Pattern> for PatternFile {
    fn from(p: Pattern) -> Self {
        PatternFile {
            format: "openstitch.pattern".into(),
            version: 1,
            kind: p.kind,
            id: p.id,
            name: p.name,
            row_shift: p.row_shift,
            paths: p
                .paths
                .iter()
                .map(|path| path.iter().map(|q| [q.x, q.y]).collect())
                .collect(),
            regions: p
                .regions
                .iter()
                .map(|r| RegionFile {
                    effect: r.effect,
                    at: [r.at.x, r.at.y],
                })
                .collect(),
        }
    }
}

impl Pattern {
    /// The pattern as an `openstitch.pattern` JSON document.
    pub fn to_json(&self) -> String {
        serde_json::to_string(&PatternFile::from(self.clone())).expect("patterns serialize")
    }

    /// The unit box of this kind: (min x, min y, max x, max y).
    pub fn unit_box(kind: PatternKind) -> (f64, f64, f64, f64) {
        match kind {
            PatternKind::Motif => (-0.5, -1.0, 1.5, 1.0),
            PatternKind::Decorative => (-0.5, 0.0, 1.5, 1.0),
            PatternKind::Fill => (0.0, 0.0, 1.0, 1.0),
        }
    }
}

/// Limits of the format: at most 64 paths and 4000 points per pattern.
pub const MAX_PATHS: usize = 64;
pub const MAX_POINTS: usize = 4000;

/// Parses and validates one `openstitch.pattern` document (at most 1 MiB).
pub fn parse(json: &str) -> Result<Pattern, String> {
    if json.len() > MAX_DOCUMENT {
        return Err("pattern document larger than 1 MiB".into());
    }
    let f: PatternFile = serde_json::from_str(json).map_err(|e| e.to_string())?;
    validate(f)
}

/// Largest pattern document accepted, bytes.
pub const MAX_DOCUMENT: usize = 1 << 20;

fn validate(f: PatternFile) -> Result<Pattern, String> {
    if f.format != "openstitch.pattern" || f.version != 1 {
        return Err("not an openstitch.pattern version 1 document".into());
    }
    let id_ok = !f.id.is_empty()
        && f.id.len() <= 64
        && f.id
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-');
    if !id_ok {
        return Err("id must be 1-64 characters a-z, 0-9 or -".into());
    }
    if f.name.is_empty() || f.name.len() > 128 {
        return Err("name must be 1-128 bytes".into());
    }
    if !(0.0..=1.0).contains(&f.row_shift) {
        return Err("rowShift must be in 0...1".into());
    }
    let count: usize = f.paths.iter().map(Vec::len).sum();
    if f.paths.is_empty() || f.paths.len() > MAX_PATHS || count > MAX_POINTS {
        return Err(format!(
            "needs 1-{MAX_PATHS} paths and at most {MAX_POINTS} points"
        ));
    }
    let (x0, y0, x1, y1) = Pattern::unit_box(f.kind);
    let (lo, hi) = ((x0, y0), (x1, y1));
    let mut paths = Vec::new();
    for p in &f.paths {
        if p.len() < 2 {
            return Err("every path needs at least 2 points".into());
        }
        let pts: Vec<Vec2> = p.iter().map(|&[x, y]| v2(x, y)).collect();
        if pts.iter().any(|q| {
            !(q.x.is_finite() && q.y.is_finite())
                || q.x < lo.0
                || q.x > hi.0
                || q.y < lo.1
                || q.y > hi.1
        }) {
            return Err("points must be finite and inside the pattern's unit box".into());
        }
        paths.push(pts);
    }
    let close = |a: Vec2, b: Vec2| a.distance(b) < 1e-6;
    match f.kind {
        PatternKind::Motif => {
            if paths.len() != 1
                || !close(paths[0][0], v2(0.0, 0.0))
                || !close(*paths[0].last().expect("2+ points"), v2(1.0, 0.0))
            {
                return Err("a motif is one path from (0, 0) to (1, 0)".into());
            }
        }
        PatternKind::Decorative => {
            for p in &paths {
                let (a, b) = (p[0], *p.last().expect("2+ points"));
                if a.x != 0.0 || b.x != 1.0 || (a.y - b.y).abs() > 1e-6 {
                    return Err("decorative paths run from (0, y) to (1, y)".into());
                }
            }
        }
        PatternKind::Fill => {}
    }
    if !f.regions.is_empty() && f.kind != PatternKind::Fill {
        return Err("only fill/stamp patterns have embossed or engraved regions".into());
    }
    if f.regions.len() > MAX_REGIONS {
        return Err(format!("at most {MAX_REGIONS} regions"));
    }
    let mut regions = Vec::new();
    for r in &f.regions {
        let [x, y] = r.at;
        if !(x.is_finite() && y.is_finite())
            || !(0.0..=1.0).contains(&x)
            || !(0.0..=1.0).contains(&y)
        {
            return Err("region points must be inside the unit tile".into());
        }
        regions.push(PatternRegion {
            effect: r.effect,
            at: v2(x, y),
        });
    }
    Ok(Pattern {
        kind: f.kind,
        id: f.id,
        name: f.name,
        row_shift: f.row_shift,
        paths,
        regions,
    })
}

